:root {
  --navy: #203743;
  --mint: #d8efe7;
  --coral: #ef8166;
}

.parcel-card {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 460px;
  padding: 14px 16px;
  background: var(--mint);
  border: 2px solid var(--navy);
  border-radius: 14px;
}

.parcel-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  background: var(--coral);
  border-radius: 10px;
  font-size: 20px;
}

.parcel-copy {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--navy);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.parcel-copy h2 {
  margin: 0;
  color: var(--navy);
  font-size: 18px;
  line-height: 1.1;
}

.pickup-code {
  padding: 8px 10px;
  background: var(--navy);
  border-radius: 8px;
  color: var(--mint);
  font-size: 14px;
  letter-spacing: 0.06em;
}
